import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const primitiveResults = [];
  let disposed = false;

  const surface = vec3(0.043, 0.043, 0.063);
  const ink = vec3(0.086, 0.086, 0.114);
  const paper = vec3(0.910, 0.925, 0.949);
  const accent = vec3(1.0, 0.165, 0.220);

  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropY = uv().y;
  const backdropGradient = smoothstep(0.0, 1.0, backdropY);
  backdropMaterial.colorNode = mix(
    surface,
    mix(ink, vec3(0.12, 0.12, 0.15), backdropGradient),
    smoothstep(0.1, 0.9, backdropY)
  );

  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMaterial);
  backdrop.position.set(0, -0.15, -2.5);
  root.add(backdrop);
  resources.push(backdrop.geometry, backdrop.material);

  const cardMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2'
  });

  const card = new Mesh(new PlaneGeometry(2.65, 1.66), cardMaterial);
  card.position.set(0, 0.05, 0);
  root.add(card);
  resources.push(card.geometry, card.material);

  const frameMaterial = new MeshBasicNodeMaterial({
    color: '#16161d'
  });

  const frameTop = new Mesh(new BoxGeometry(2.78, 0.055, 0.08), frameMaterial);
  const frameBottom = new Mesh(new BoxGeometry(2.78, 0.055, 0.08), frameMaterial);
  const frameLeft = new Mesh(new BoxGeometry(0.055, 1.72, 0.08), frameMaterial);
  const frameRight = new Mesh(new BoxGeometry(0.055, 1.72, 0.08), frameMaterial);

  frameTop.position.set(0, 0.90, 0.08);
  frameBottom.position.set(0, -0.80, 0.08);
  frameLeft.position.set(-1.36, 0.05, 0.08);
  frameRight.position.set(1.36, 0.05, 0.08);

  root.add(frameTop, frameBottom, frameLeft, frameRight);
  resources.push(frameMaterial, frameTop.geometry, frameBottom.geometry, frameLeft.geometry, frameRight.geometry);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });

  const accentBar = new Mesh(new BoxGeometry(0.48, 0.035, 0.06), accentMaterial);
  accentBar.position.set(-0.92, -0.99, 0.14);
  root.add(accentBar);
  resources.push(accentBar.geometry, accentMaterial);

  const foregroundMaterial = new MeshBasicNodeMaterial();
  foregroundMaterial.colorNode = mix(
    vec3(0.55, 0.56, 0.59),
    paper,
    smoothstep(0.0, 1.0, uv().y)
  );

  const foreground = new Mesh(new PlaneGeometry(0.34, 0.025), foregroundMaterial);
  foreground.position.set(0.98, -0.99, 0.15);
  root.add(foreground);
  resources.push(foreground.geometry, foreground.material);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
      resources.push(texture);
    }).catch(() => {});
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result) primitiveResults.push(result);
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.clear();
  };

  return root;
}
